        extra: [String: JSONValue] = [:]
    ) async throws -> JSONValue {
        try await self.engine.command(
            "file.watchFolder",
            [
                "folder": folder.jsonValue,
                "stop": stop?.jsonValue,
            ],
            extra: extra
        )
    }
}
